  ["git status --short && git branch --show-current", 4000],
  ["gh pr view 2134 --json number,title,body,author,state,baseRefName,headRefName,files,commits,comments,reviews,statusCheckRollup,url", 30000],
  ["gh pr view 2135 --json number,title,body,author,state,baseRefName,headRefName,files,commits,comments,reviews,statusCheckRollup,url", 30000],
  ["gh pr view 2136 --json number,title,body,author,state,baseRefName,headRefName,files,commits,comments,reviews,statusCheckRollup,url", 30000],
  ["gh pr diff 2135", 50000],
  ["gh pr diff 2136", 50000]
];
const rs = await Promise.all(cmds.map(async ([cmd,max]) => {
  const r = await tools.exec_command({cmd, workdir:"/Users/gtrrz-victor/wks/cli/exploring-entire",yield_time_ms:30000,max_output_tokens:max});
  return `COMMAND: ${cmd}\nEXIT: ${r.exit_code}\n${r.output}`;
}));
rs.forEach(text);

