+	dir := t.TempDir()
+	stalled := stalledScript(t)
+	stalledNames := []string{"disc-par-slow1", "disc-par-slow2", "disc-par-slow3", "disc-par-slow4"}
+	for _, name := range stalledNames {
+		writeAgentBinary(t, dir, name, stalled)
