297	// inspectBinary reports whether binPath is worth executing. It returns
298	// (false, nil) for entries that aren't plugins at all — a directory, or a file
299	// that vanished between glob and stat — and an error for a file that looks like
300	// a plugin but cannot be run.
301	func inspectBinary(binPath string) (bool, error) {
302		// binPath is not user input: it comes from a $PATH glob or exec.LookPath, and
303		// a name carrying a path separator is rejected before lookup.
304		finfo, err := os.Stat(binPath) //nolint:gosec // G703: path comes from $PATH, not from user input
305		if err != nil {
306			if errors.Is(err, os.ErrNotExist) {
307				return false, nil
308			}
309			return false, fmt.Errorf("inspecting external agent binary %q: %w", binPath, err)
310		}
311		if finfo.IsDir() {
312			return false, nil
313		}
314		// Windows doesn't set execute bits; executability there comes from PATHEXT.
315		if runtime.GOOS != osWindows && finfo.Mode()&0o111 == 0 {
316			return false, fmt.Errorf("%w: %q", ErrNotExecutable, binPath)
317		}
318		return true, nil
319	}
