321	// loadExternalAgent runs the binary's "info" subcommand under the per-binary
322	// budget and wraps the result. It never touches the registries, so callers
323	// decide whether a failure is returned, recorded, or both.
324	func loadExternalAgent(ctx context.Context, cand candidate) (agent.Agent, error) {
325		// ctx stays the CALLER's; the budget gets its own name. Shadowing ctx here
326		// would hide caller cancellation behind the derived deadline.
327		runCtx, cancel := context.WithTimeout(ctx, infoTimeout)
328		defer cancel()
329	
330		ea, err := New(runCtx, cand.binPath)
331		if err != nil {
332			return nil, fmt.Errorf("loading info for external agent %q from binary %q: %w",
333				cand.name, cand.binPath, classifyLoadError(ctx, runCtx, err))
334		}
335	
336		wrapped, err := Wrap(ea)
337		if err != nil {
338			return nil, fmt.Errorf("wrapping external agent %q from binary %q: %w", cand.name, cand.binPath, err)
339		}
