336			agent.RegisterExternalFailure(name, binPath, err)
337			return err
338		}
339		if !ok {
340			return nil
341		}
342	
343		ag, err := loadExternalAgent(ctx, c)
344		if err != nil {
345			agent.RegisterExternalFailure(name, binPath, err)
346			return err
347		}
348		applyProbeResult(ctx, probeResult{candidate: c, ag: ag})
349		return nil
350	}
