130	func collectCandidates(ctx context.Context, pathEnv string) []candidate {
131		usable := make(map[types.AgentName]bool)
132		for _, name := range agent.List() {
133			usable[name] = true
134		}
135		probed := agent.ProbedExternalBinaries()
136	
137		seen := make(map[types.AgentName]bool) // first $PATH dir wins, as $PATH itself does
138		var candidates []candidate
139	
140		for _, dir := range filepath.SplitList(pathEnv) {
141			matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
142			if err != nil {
143				continue // skip unreadable directories
144			}
145			for _, binPath := range matches {
146				// Dedupe on the derived agent name, not the file name: on Windows
147				// entire-agent-foo.exe and entire-agent-foo.com both derive agent
148				// "foo", and PATHEXT decides which one actually runs.
149				name := derivedAgentName(binPath)
150				if name == "" || seen[name] {
151					continue
152				}
153				seen[name] = true
154	
155				// Already probed this exact binary in this process, ready or failed.
156				if _, ok := probed[binPath]; ok {
157					continue
158				}
159	
160				if usable[name] {
161					// A built-in always wins, and the colliding binary is never
162					// executed. The gated DiscoverAndRegister runs inside the hook
163					// trees, so an override would let a binary dropped anywhere on
164					// $PATH take over transcript reads and checkpoint writes on
165					// every hook. Warn (not Debug) so the attempt is visible.
166					logging.Warn(ctx, "ignoring external agent that shadows an existing agent",
167						slog.String("binary", binPath),
168						slog.String("agent", string(name)))
169					continue
170				}
171	
172				ok, err := inspectBinary(name, binPath)
173				if err != nil {
174					agent.RegisterExternalFailure(name, binPath, err)
175					continue
176				}
177				if !ok {
178					continue
179				}
180				candidates = append(candidates, candidate{name: name, path: binPath})
181			}
182		}
183		return candidates
184	}
185	
186	// derivedAgentName maps a binary path to the registry name it would claim.
187	func derivedAgentName(binPath string) types.AgentName {
188		base := StripExeExt(filepath.Base(binPath))
189		return types.AgentName(strings.TrimPrefix(base, binaryPrefix))
190	}
191	
192	// inspectBinary reports whether binPath is worth executing. It returns
193	// (false, nil) when the path has gone away — a binary that vanished between the
194	// glob and the stat is not a broken plugin — and (false, err) when the file is
195	// there but cannot be an agent.
196	func inspectBinary(name types.AgentName, binPath string) (bool, error) {
197		// G703: binPath comes from a $PATH glob or exec.LookPath, both of which are
198		// process inputs we already trust to name executables.
199		finfo, err := os.Stat(binPath) //nolint:gosec // path is a $PATH-resolved binary, not user input
200		if err != nil {
201			if errors.Is(err, os.ErrNotExist) {
202				return false, nil
203			}
204			return false, fmt.Errorf("inspecting external agent %q binary %q: %w", name, binPath, err)
205		}
206		if finfo.IsDir() {
207			return false, fmt.Errorf("external agent %q path %q is a directory, not an executable", name, binPath)
208		}
209		// Windows does not set execute bits.
210		if runtime.GOOS != osWindows && finfo.Mode()&0o111 == 0 {
211			return false, fmt.Errorf("external agent %q binary %q: %w", name, binPath, ErrNotExecutable)
212		}
213		return true, nil
214	}
215	
216	// probeCandidates asks every candidate for its `info` concurrently and returns
217	// the results in candidate order, so registration stays deterministic even
218	// though completion order is not.
219	//
220	// No worker pool: the realistic candidate count is a handful, and a cap would
221	// serialize exactly the case this concurrency exists for.
222	func probeCandidates(ctx context.Context, candidates []candidate) []probeResult {
223		results := make(chan probeResult, len(candidates))
224		for _, c := range candidates {
225			go func() {
226				ag, err := loadExternalAgent(ctx, c)
227				results <- probeResult{candidate: c, ag: ag, err: err}
228			}()
229		}
230	
231		byPath := make(map[string]probeResult, len(candidates))
232		for range candidates {
233			r := <-results
234			byPath[r.path] = r
235		}
236	
237		ordered := make([]probeResult, 0, len(candidates))
238		for _, c := range candidates {
239			ordered = append(ordered, byPath[c.path])
240		}
241		return ordered
242	}
243	
244	// loadExternalAgent runs `info` on one binary under its own budget and wraps
245	// the result. It never touches the registry, so it is safe to run concurrently.
246	func loadExternalAgent(ctx context.Context, c candidate) (agent.Agent, error) {
247		// Derived from the caller, so a tighter caller deadline still wins.
248		probeCtx, cancel := context.WithTimeout(ctx, infoTimeout)
249		defer cancel()
250	
251		ea, err := New(probeCtx, c.path)
252		if err != nil {
253			return nil, classifyLoadError(ctx, probeCtx, c, err)
254		}
255		wrapped, err := Wrap(ea)
256		if err != nil {
257			return nil, fmt.Errorf("wrapping external agent %q from binary %q: %w", c.name, c.path, err)
258		}
259		return wrapped, nil
260	}
261	
262	// classifyLoadError labels a failed `info` call so the caller can tell a budget
263	// breach from a genuinely broken plugin.
264	func classifyLoadError(caller, probe context.Context, c candidate, err error) error {
265		wrapped := fmt.Errorf("loading info for external agent %q from binary %q: %w", c.name, c.path, err)
266		if callerErr := caller.Err(); callerErr != nil {
267			return fmt.Errorf("%w: %w", callerErr, wrapped)
268		}
269		if probeErr := probe.Err(); probeErr != nil {
270			return fmt.Errorf("%w after %s (%w): %w", ErrInfoTimeout, infoTimeout, probeErr, wrapped)
271		}
272		return wrapped
273	}
274	
275	// applyProbeResult records one probe outcome in the registry. Called only from
276	// the goroutine that owns discovery, so registration order is deterministic.
277	func applyProbeResult(ctx context.Context, r probeResult) {
278		if r.err != nil {
279			agent.RegisterExternalFailure(r.name, r.path, r.err)
280			logging.Debug(ctx, "external agent found but not loadable",
281				slog.String("binary", r.path),
282				slog.String("agent", string(r.name)),
283				slog.String("error", r.err.Error()))
284			return
285		}
286	
287		agent.RegisterExternal(r.name, r.path, func() agent.Agent { return r.ag })
288	
289		// The registry key comes from the file name, and every caller resolves
290		// agents by that key, so a binary reporting a different name still works.
291		// Say so rather than leaving the inconsistency to surface in logs later.
292		if declared := r.ag.Name(); declared != r.name {
293			logging.Warn(ctx, "external agent reports a name that differs from its binary",
294				slog.String("binary", r.path),
295				slog.String("registered", string(r.name)),
296				slog.String("declared", string(declared)))
297		}
298	
299		logging.Debug(ctx, "registered external agent",
300			slog.String("name", string(r.name)),
301			slog.String("type", string(r.ag.Type())),
302			slog.String("binary", r.path))
303	}
304	
305	// discoverAndRegisterNamed resolves one named binary through $PATH instead of
306	// globbing. Unlike the scan, it surfaces the failure to its caller as well as
307	// recording it, because the caller named this agent explicitly.
308	func discoverAndRegisterNamed(ctx context.Context, name types.AgentName) error {
309		if name == "" {
310			return nil
311		}
312		if strings.ContainsAny(string(name), `/\`) {
313			return fmt.Errorf("invalid external agent name %q: contains path separators", name)
314		}
315		if _, err := agent.Get(name); err == nil {
316			return nil
317		}
318		if err := ctx.Err(); err != nil {
319			return fmt.Errorf("discovering external agent %q: %w", name, err)
320		}
321	
322		binName := binaryPrefix + string(name)
323		binPath, err := lookPathExternalAgent(binName)
324		if err != nil {
325			// A missing binary means "no such plugin, fall through to other
326			// resolution" — not a broken agent. Callers depend on the nil.
327			if errors.Is(err, exec.ErrNotFound) {
328				return nil
329			}
330			return fmt.Errorf("looking up external agent %q binary %q: %w", name, binName, err)
331		}
332	
333		c := candidate{name: name, path: binPath}
334		ok, err := inspectBinary(name, binPath)
335		if err != nil {
336			agent.RegisterExternalFailure(name, binPath, err)
337			return err
338		}
339		if !ok {
340			return nil
341		}
342	
343		ag, err := loadExternalAgent(ctx, c)
344		if err != nil {
345			agent.RegisterExternalFailure(name, binPath, err)
346			return err
347		}
348		applyProbeResult(ctx, probeResult{candidate: c, ag: ag})
349		return nil
350	}
