352	// StripExeExt removes Windows executable extensions (.exe, .bat, .cmd, .com)
353	// from a file name so that the derived name matches on all platforms. On Unix
354	// this is effectively a no-op because binaries have no extension.
355	//
356	// .com is included because Windows PATHEXT defaults to ".COM;.EXE;.BAT;.CMD;…",
357	// so exec.LookPath can resolve a `.com` next to a `.exe`. Without stripping
358	// it, a managed-plugin or agent-binary installer would treat foo.exe and
359	// foo.com as distinct names while PATHEXT silently picks one.
360	func StripExeExt(name string) string {
361		switch strings.ToLower(filepath.Ext(name)) {
362		case ".exe", ".bat", ".cmd", ".com":
363			return strings.TrimSuffix(name, filepath.Ext(name))
364		}
