 553	func applyAgentChanges(ctx context.Context, w io.Writer, selectedAgentNames []string, installedNames []types.AgentName, opts EnableOptions) error {
 554		installedSet := make(map[types.AgentName]struct{}, len(installedNames))
 555		for _, name := range installedNames {
 556			installedSet[name] = struct{}{}
 557		}
 558	
 559		selectedSet := make(map[string]struct{}, len(selectedAgentNames))
 560		for _, name := range selectedAgentNames {
 561			selectedSet[name] = struct{}{}
 562		}
 563	
 564		// Collect errors so partial successes are visible to the user.
 565		var errs []error
 566	
 567		var addedAgents []agent.Agent
 568		var reinstalledAgents []agent.Agent
 569		for _, name := range selectedAgentNames {
 570			ag, err := agent.Get(types.AgentName(name))
 571			if err != nil {
 572				errs = append(errs, fmt.Errorf("failed to get agent %s: %w", name, err))
 573				continue
 574			}
