	agent.Register(types.AgentName(name), func() agent.Agent {
		return nil // placeholder
	})

	dir := t.TempDir()
	marker := filepath.Join(dir, "was-executed")
	writeAgentBinary(t, dir, name, touchOnRunScript(name, marker))
	t.Setenv("PATH", dir)

