	ag, err := agent.Get(types.AgentName(name))
	if err != nil {
		t.Fatalf("agent should still be registered: %v", err)
	}
	// The placeholder factory returns nil, so it wasn't replaced.
	if ag != nil {
		t.Errorf("expected placeholder (nil) agent, got %v", ag)
